"""Add editorial upsell suggestions without modifying the live merchant catalog."""
from pathlib import Path
import json,hashlib,re,html
root=Path('dist');rules=json.loads(Path('content/store-suggestions.json').read_text());source=json.loads(Path('content/source/store-products.json').read_text());cats=json.loads(Path('content/store-categories.json').read_text())
copy={
'en':dict(title='You may also like',product='Complete your setup',cart='Add something useful to your setup',eyebrow='MT E.L.K., INC. / FIELD COMPANIONS',context='Explore related gear, calling resources and existing packages.',cartNote='Suggestions complement the items in your cart. Nothing is added automatically.',view='View options & price',about='How these suggestions are chosen',detail='Suggestions use product categories, model names and verified package contents—not purchase history. Check compatibility and current options on each product page. Prices and availability come from the live store.',shortcut='Suggested add-ons',previous='Previous suggestions',next='Next suggestions',list='Suggested products',reasons=dict(model='Replacement for this model',learn='Calling education',book='Related reading',accessory='Carry and care',package='Compare the package',related='Explore this category',explore='Explore the catalog')),
'fr':dict(title='Vous pourriez aussi aimer',product='Complétez votre équipement',cart='Complétez votre équipement utilement',eyebrow='MT E.L.K., INC. / POUR LE TERRAIN',context='Découvrez des accessoires, des ressources pédagogiques et les ensembles existants.',cartNote='Ces suggestions complètent les articles du panier. Aucun ajout automatique.',view='Voir les options et le prix',about='Comment ces suggestions sont choisies',detail='Les suggestions reposent sur les catégories, les modèles et le contenu vérifié des ensembles, sans historique d’achats. Vérifiez la compatibilité et les options sur chaque fiche. Les prix et la disponibilité proviennent de la boutique.',shortcut='Articles complémentaires',previous='Suggestions précédentes',next='Suggestions suivantes',list='Produits suggérés',reasons=dict(model='Pièce pour ce modèle',learn='Formation aux appeaux',book='Lecture complémentaire',accessory='Transport et entretien',package='Comparer l’ensemble',related='Explorer cette catégorie',explore='Explorer le catalogue')),
'es':dict(title='También le puede interesar',product='Complete su equipo',cart='Añada algo útil a su equipo',eyebrow='MT E.L.K., INC. / EQUIPO PARA EL CAMPO',context='Explore accesorios, recursos de aprendizaje y paquetes existentes.',cartNote='Estas sugerencias complementan los artículos del carrito. Nada se añade automáticamente.',view='Ver opciones y precio',about='Cómo elegimos estas sugerencias',detail='Las sugerencias se basan en categorías, modelos y contenido verificado de los paquetes, sin historial de compras. Compruebe la compatibilidad y las opciones de cada producto. Los precios y la disponibilidad provienen de la tienda.',shortcut='Complementos sugeridos',previous='Sugerencias anteriores',next='Sugerencias siguientes',list='Productos sugeridos',reasons=dict(model='Repuesto para este modelo',learn='Aprendizaje de reclamos',book='Lectura relacionada',accessory='Transporte y cuidado',package='Comparar el paquete',related='Explorar esta categoría',explore='Explorar el catálogo')),
'de':dict(title='Das könnte Ihnen auch gefallen',product='Ergänzen Sie Ihre Ausrüstung',cart='Sinnvolle Ergänzungen für Ihre Ausrüstung',eyebrow='MT E.L.K., INC. / FÜR DIE JAGD',context='Entdecken Sie passendes Zubehör, Lernmaterial und bestehende Pakete.',cartNote='Diese Vorschläge ergänzen die Artikel im Warenkorb. Es wird nichts automatisch hinzugefügt.',view='Optionen und Preis ansehen',about='So werden die Vorschläge ausgewählt',detail='Die Vorschläge basieren auf Kategorien, Modellen und geprüften Paketinhalten, nicht auf Kaufverläufen. Prüfen Sie die Kompatibilität und Optionen auf der Produktseite. Preise und Verfügbarkeit stammen aus dem Live-Shop.',shortcut='Empfohlene Ergänzungen',previous='Vorherige Vorschläge',next='Weitere Vorschläge',list='Produktvorschläge',reasons=dict(model='Ersatzteil für dieses Modell',learn='Wildlocker-Lernmaterial',book='Passende Lektüre',accessory='Transport und Pflege',package='Paket vergleichen',related='Diese Kategorie entdecken',explore='Sortiment entdecken'))}
for lang,extra in json.loads(Path('content/store-suggestion-visibility.json').read_text()).items():copy[lang].update(extra)
products=[]
for p in source['products']:
 name=p['name'];kind='package' if name.startswith('*') else 'part' if 'bands-reeds' in p['categories'] else 'media' if name.endswith(('DVD','CD')) else 'book' if name.endswith('BOOK') else 'accessory' if p['id'] in rules['accessories'] else 'blind' if 'blinds' in p['categories'] else 'call'
 products.append({k:p[k] for k in ['id','name','image','categories']}|{'kind':kind,'unavailable':p['stock_note'].startswith('unavailable')})
ids={p['id'] for p in products};assert len(ids)==len(products) and len(ids)>0
for values in rules['pairings'].values():assert all(i in ids for i in values)
for values in rules['package_contents'].values():assert all(i in ids for i in values)
data={**{k:rules[k] for k in ['pairings','package_alternatives','package_contents','default_products','excluded_products']},'species':['elk','mule-deer','whitetail','antelope','predator'],'categories':[{k:c[k] for k in ['id','slug']} for c in cats],'products':products}
raw=json.dumps(data,ensure_ascii=False,separators=(',',':'));asset='store-suggestions-'+hashlib.sha256(raw.encode()).hexdigest()[:12]+'.json';(root/'assets'/asset).write_text(raw)
def digest(name):return hashlib.sha256((root/name).read_bytes()).hexdigest()[:12]
p=root/'store-suggestions.js';s=p.read_text();s=re.sub(r"from './store-suggestion-rules.js(?:\?[^']*)?'", "from './store-suggestion-rules.js?v="+digest('store-suggestion-rules.js')+"'",s);p.write_text(s)
p=root/'store.js';s=p.read_text();s=re.sub(r"from './store-suggestions.js(?:\?[^']*)?'", "from './store-suggestions.js?v="+digest('store-suggestions.js')+"'",s);p.write_text(s)
for lang,c in copy.items():
 p=root/('' if lang=='en' else lang)/'shop/index.html';s=p.read_text();s=re.sub(r'<section class="store-suggestions".*?</section>','',s,flags=re.S);s=re.sub(r'<a class="store-suggestions-shortcut".*?</a>','',s,flags=re.S);s=re.sub(r'<link rel="stylesheet" href="/store-suggestions.css[^\"]*">','',s)
 encoded=json.dumps(c,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 section=f'<section class="store-suggestions" id="store-recommendations" data-store-suggestions data-catalog="/assets/{asset}" aria-labelledby="store-suggestions-title" hidden><div class="store-suggestions-heading"><div><p class="eyebrow">{c["eyebrow"]}</p><h2 id="store-suggestions-title" tabindex="-1">{c["title"]}</h2></div></div><p data-suggestion-context>{c["context"]}</p><ul class="store-suggestion-list" id="store-suggestion-list" data-suggestion-list aria-label="{c["list"]}"></ul><div class="store-suggestions-browse"><p class="store-suggestions-swipe">{c["swipe"]}</p><div class="store-suggestions-nav"><button type="button" data-suggestion-direction="-1" aria-label="{c["previous"]}" aria-controls="store-suggestion-list">←</button><span data-suggestion-position role="status" aria-live="polite" aria-atomic="true"></span><button type="button" data-suggestion-direction="1" aria-label="{c["next"]}" aria-controls="store-suggestion-list">→</button></div></div><details><summary>{c["about"]}</summary><p>{c["detail"]}</p></details><script type="application/json" data-suggestion-copy>{encoded}</script></section>'
 marker='<section class="store-model-guide"';assert marker in s;s=s.replace(marker,section+marker,1)
 marker='</div></div><p id="store-status"';assert marker in s;s=s.replace(marker,f'</div><a class="store-suggestions-shortcut" href="#store-recommendations" hidden>{c["shortcut"]} ↓</a></div><p id="store-status"',1)
 s=s.replace('</head>',f'<link rel="stylesheet" href="/store-suggestions.css?v={digest("store-suggestions.css")}"></head>');s=re.sub(r'/store.js\?v=[a-f0-9]+','/store.js?v='+digest('store.js'),s);p.write_text(s)
Path('content/store-suggestions-locales.json').write_text(json.dumps(copy,ensure_ascii=False,indent=2)+'\n')
print(f'Added editorial recommendations to 4 shop pages, using {len(products)} verified products and unchanged native checkout.')
